async function submitContactMessage(formData: FormData) {
  'use server';

  const name = formData.get('name') as string | null;
  const email = formData.get('email') as string | null;
  const message = formData.get('message') as string | null;

  // JavaScript validation - check that all fields are provided
  const errors: string[] = [];
  if (!name || typeof name !== 'string' || name.trim() === '') {
    errors.push('Name is required');
  }
  if (!email || typeof email !== 'string' || email.trim() === '') {
    errors.push('Email is required');
  }
  if (!message || typeof message !== 'string' || message.trim() === '') {
    errors.push('Message is required');
  }

  if (errors.length > 0) {
    return { success: false, errors };
  }

  // Simulate saving the contact message (e.g., to a database)
  console.log('Contact message received:', {
    name: name!.trim(),
    email: email!.trim(),
    message: message!.trim()
  });

  return { success: true };
}

export default function ContactForm() {
  return (
    <div>
      <h2>Contact Us</h2>
      <form action={submitContactMessage} className="flex flex-col gap-4 max-w-md">
        <div>
          <label htmlFor="name" className="block text-sm font-medium mb-1">
            Name
          </label>
          <input
            id="name"
            name="name"
            type="text"
            placeholder="Your name"
            required
            className="w-full px-3 py-2 border rounded-md"
          />
        </div>
        <div>
          <label htmlFor="email" className="block text-sm font-medium mb-1">
            Email
          </label>
          <input
            id="email"
            name="email"
            type="email"
            placeholder="your@email.com"
            required
            className="w-full px-3 py-2 border rounded-md"
          />
        </div>
        <div>
          <label htmlFor="message" className="block text-sm font-medium mb-1">
            Message
          </label>
          <textarea
            id="message"
            name="message"
            placeholder="Your message..."
            required
            rows={4}
            className="w-full px-3 py-2 border rounded-md resize-y"
